"""Claims read directly in the models/completion/Gabriel--Ulmer sheets."""
unit(918,5,'Pointwise models, target change and the Yoneda test',[66,67,68,69],'1–83','« construction des limites »; withdrawn final paragraph')
unit(919,5,'Free completion under all or bounded limits',[70,71,72,73,74,75,76,77],'85–253','« Mais attention »; « vérifier ... une U-catégorie »')
